{"implementation":"def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    intra = 0
    inter = 0
    for u, v, w in edges:
        if refinement[u] == refinement[v]:
            intra += w
        else:
            inter += w
    return {"intra": intra, "inter": inter}
